select id, 3, $$forEach ignores returned promises. Use a for...of loop with await, or Promise.all(nums.map(...)).$$ from new_challenge;

with new_challenge as (
  insert into public.bug_challenges (
    title, language, bug_category, difficulty, function_name,
    broken_code, correct_code, problem_description, symptom_description,
    explanation, test_cases, status
  ) values (
    $$Missing await turns the total into text$$,
    $$javascript$$,
    $$async_race_condition$$,
    $$medium$$,
    $$sumDelayed$$,
    $$function delay(n) {
    return new Promise((resolve) => setTimeout(() => resolve(n), 1));
}

async function sumDelayed(nums) {
    let total = 0;
    for (const n of nums) {
        total += delay(n);
    }
    return total;
}$$,
    $$function delay(n) {
    return new Promise((resolve) => setTimeout(() => resolve(n), 1));
}

async function sumDelayed(nums) {
    let total = 0;
    for (const n of nums) {
        total += await delay(n);
    }
    return total;
}$$,
    $$sumDelayed(nums) should add up numbers that each arrive asynchronously, resolving to the total.$$,
    $$sumDelayed([1, 2, 3]) resolves to "0[object Promise][object Promise][object Promise]" instead of 6.$$,
    $$delay() returns a Promise, and without await you add the Promise object itself rather than its resolved value. JavaScript coerces it to the string "[object Promise]", so the total silently becomes text instead of throwing. A result containing "[object Promise]" is almost always a missing await.$$,
    $$[{"input":[[1,2,3]],"expected_output":6},{"input":[[10]],"expected_output":10},{"input":[[]],"expected_output":0}]$$::jsonb,
    'published'
  )
  returning id
)
