select id, 1, $$Look at the exact text in the result — what type is being added to the total?$$ from new_challenge
union all
select id, 2, $$delay() hands back a Promise, not a number.$$ from new_challenge
union all
select id, 3, $$Add await before delay(n) so the resolved value is what gets added.$$ from new_challenge;

with new_challenge as (
  insert into public.bug_challenges (
    title, language, bug_category, difficulty, function_name,
    broken_code, correct_code, problem_description, symptom_description,
    explanation, test_cases, status
  ) values (
    $$map returns promises instead of values$$,
    $$javascript$$,
    $$async_race_condition$$,
    $$medium$$,
    $$wordLengths$$,
    $$async function wordLengths(words) {
    return words.map(async (word) => word.length);
}$$,
    $$async function wordLengths(words) {
    return Promise.all(words.map(async (word) => word.length));
}$$,
    $$wordLengths(words) should resolve to a list of each word's length.$$,
    $$wordLengths(["abc", "defg"]) resolves to [{}, {}] instead of [3, 4].$$,
    $$An async callback always returns a Promise, so map produces an array *of Promises*, and awaiting the outer function only unwraps one layer — not the promises inside the array. Promise.all turns an array of promises into a promise of an array, which is what you actually want.$$,
    $$[{"input":[["abc","defg"]],"expected_output":[3,4]},{"input":[["hi"]],"expected_output":[2]}]$$::jsonb,
    'published'
  )
  returning id
)
insert into public.hints (bug_challenge_id, hint_order, hint_text)
select id, 1, $$The array has the right number of entries but the wrong contents. What are those entries?$$ from new_challenge
union all
select id, 2, $$An async function always returns a Promise — even a one-line one inside map.$$ from new_challenge
union all
select id, 3, $$Wrap the mapped array in Promise.all() so every inner promise resolves.$$ from new_challenge;

